1	import {
2	  ChangeDetectionStrategy,
3	  Component,
4	  DestroyRef,
5	  ElementRef,
6	  afterNextRender,
7	  computed,
8	  inject,
9	  signal,
10	  viewChild,
11	} from '@angular/core';
12	import { ActivatedRoute, Router } from '@angular/router';
13	import { Subscription, forkJoin } from 'rxjs';
14	import { QuoteSessionStore, Step1Values } from '../../core/session/quote-session.store';
15	import { RichTextComponent } from '../../shared/ui/rich-text/rich-text.component';
16	import { StepperComponent } from '../../shared/ui/stepper/stepper.component';
17	import { Plan } from '../plan-list/data/plan.model';
18	import { PlanService } from '../plan-list/data/plan.service';
19	import { agesFromStep1 } from '../plan-list/pricing/ages-from-step1';
20	import { formatPrice } from '../plan-list/pricing/format-price';
21	import { simulatePrice } from '../plan-list/pricing/simulate-price';
22	import { FormFieldService } from '../quote-form/data/form-field.service';
23	import { FormSections } from '../quote-form/data/form-field.model';
24	import { WizardCountry } from '../quote-wizard/wizard-country.service';
25	import { PaymentService } from './payment/payment.service';
26	import { createQuoteNumber } from './payment/quote-number';
27	import { SummaryRows, buildSummaryRows } from './summary-rows';
28	
29	type PaymentState = 'idle' | 'processing' | 'rejected';
30	
31	interface ChosenPlan {
32	  plan: Plan;
33	  finalPrice: number;
34	  /** Amount only, e.g. "$ 189.000" (the "/ mes" is rendered separately). */
35	  amount: string;
36	}
37	
38	const PER_MONTH_SUFFIX = / \/ mes$/;
39	
40	@Component({
41	  selector: 'app-summary-page',
42	  imports: [StepperComponent, RichTextComponent],
43	  changeDetection: ChangeDetectionStrategy.OnPush,
44	  templateUrl: './summary.page.html',
45	  styleUrl: './summary.page.scss',
46	})
47	export class SummaryPage {
48	  private readonly wizardCountry = inject(WizardCountry);
49	  private readonly planService = inject(PlanService);
50	  private readonly fieldService = inject(FormFieldService);
51	  private readonly payment = inject(PaymentService);
52	  private readonly session = inject(QuoteSessionStore);
53	  private readonly router = inject(Router);
54	  private readonly route = inject(ActivatedRoute);
55	  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
56	  private readonly destroyRef = inject(DestroyRef);
57	
58	  private readonly dialog = viewChild<ElementRef<HTMLDialogElement>>('termsDialog');
59	  private readonly termsLink = viewChild<ElementRef<HTMLButtonElement>>('termsLink');
60	
61	  protected readonly steps = ['Tus datos', 'Elige tu plan', 'Resumen'];
62	  protected readonly loading = signal(true);
63	  protected readonly failed = signal(false);
64	  protected readonly paymentState = signal<PaymentState>('idle');
65	  protected readonly accepted = signal(this.session.readTermsAccepted());
66	
67	  private readonly fields = signal<FormSections>({ policyholder: [], vehicle: [] });
68	  private readonly values = signal<Step1Values>({});
69	  protected readonly chosen = signal<ChosenPlan | null>(null);
70	  private loadSub: Subscription | null = null;
71	  private paySub: Subscription | null = null;
72	
73	  protected readonly rows = computed<SummaryRows>(() =>
74	    buildSummaryRows(this.fields(), this.values(), this.wizardCountry.country()?.numberLocale ?? 'es'),
75	  );
76	  protected readonly terms = computed(() => this.wizardCountry.country()?.termsAndConditions ?? []);
77	  protected readonly hasTerms = computed(() => this.terms().length > 0);
78	  protected readonly processing = computed(() => this.paymentState() === 'processing');
79	  protected readonly canPay = computed(
80	    () =>
81	      !this.loading() &&
82	      !this.failed() &&
83	      this.chosen() !== null &&
84	      this.hasTerms() &&
85	      this.accepted() &&
86	      !this.processing(),
87	  );
88	
89	  constructor() {
90	    afterNextRender(() => this.host.nativeElement.querySelector<HTMLElement>('h1')?.focus());
91	    this.destroyRef.onDestroy(() => {
92	      this.loadSub?.unsubscribe();
93	      this.paySub?.unsubscribe();
94	    });
95	    this.load();
96	  }
97	
98	  protected load(): void {
99	    const country = this.wizardCountry.country();
100	    if (!country) return;
101	    this.loadSub?.unsubscribe();
102	    this.loading.set(true);
103	    this.failed.set(false);
104	    this.loadSub = forkJoin({
105	      plans: this.planService.load(country.code),
106	      fields: this.fieldService.load(country.code),
107	    }).subscribe({
108	      next: ({ plans, fields }) => {
109	        const values = this.session.readStep1();
110	        const plan = plans.find((p) => p.id === this.session.readPlanId());
111	        if (!plan) {
112	          // FR-010: the chosen plan is no longer offered.
113	          this.session.clearPlan();
114	          void this.router.navigate(['..', 'plans'], { relativeTo: this.route });
115	          return;
116	        }
117	        const { driverAge, vehicleAge } = agesFromStep1(values, new Date());
118	        const finalPrice = simulatePrice(plan.basePrice, driverAge, vehicleAge, country);
119	        this.values.set(values);
120	        this.fields.set(fields);
121	        this.chosen.set({
122	          plan,
123	          finalPrice,
124	          amount: formatPrice(finalPrice, country).replace(PER_MONTH_SUFFIX, ''),
125	        });
126	        this.loading.set(false);
127	      },
128	      error: () => {
129	        this.failed.set(true);
130	        this.loading.set(false);
131	      },
132	    });
133	  }
134	
135	  protected toggleTerms(event: Event): void {
136	    const accepted = (event.target as HTMLInputElement).checked;
137	    this.accepted.set(accepted);
138	    this.session.acceptTerms(accepted);
139	  }
140	
141	  protected openTerms(): void {
142	    const dialog = this.dialog()?.nativeElement;
143	    if (!dialog) return;
144	    if (typeof dialog.showModal === 'function') dialog.showModal();
145	    else dialog.setAttribute('open', '');
146	  }
147	
148	  protected closeTerms(): void {
149	    const dialog = this.dialog()?.nativeElement;
150	    if (!dialog) return;
151	    if (typeof dialog.close === 'function') dialog.close();
152	    else dialog.removeAttribute('open');
153	    this.termsClosed();
154	  }
155	
156	  /** Esc, "Cerrar" and "Entendido" all end here: focus goes back to the link. */
157	  protected termsClosed(): void {
158	    this.termsLink()?.nativeElement.focus();
159	  }
160	
161	  protected edit(): void {
162	    void this.router.navigate(['..'], { relativeTo: this.route });
163	  }
164	
165	  protected changePlan(): void {
166	    void this.router.navigate(['..', 'plans'], { relativeTo: this.route });
167	  }
168	
169	  /** R7: only an idle or rejected page pays; the button is disabled while processing. */
170	  protected pay(): void {
171	    const state = this.paymentState();
172	    if (state !== 'idle' && state !== 'rejected') return;
173	    const country = this.wizardCountry.country();
174	    const chosen = this.chosen();
175	    if (!country || !chosen || !this.hasTerms() || !this.accepted()) return;
176	
177	    this.paymentState.set('processing');
178	    const maskedKeys = [...this.fields().policyholder, ...this.fields().vehicle]
179	      .filter((field) => field.maskedInSummary)
180	      .map((field) => field.key);
181	    this.paySub?.unsubscribe();
182	    this.paySub = this.payment.pay(this.values(), maskedKeys).subscribe({
183	      next: (result) => {
184	        if (result === 'approved') this.approve(country.code, chosen, country);
185	        else this.paymentState.set('rejected');
186	      },
187	      error: () => this.paymentState.set('rejected'),
188	    });
189	  }
190	
191	  private approve(
192	    countryCode: string,
193	    chosen: ChosenPlan,
194	    country: { currency: string; numberLocale: string },
195	  ): void {
196	    const now = new Date();
197	    // Receipt first, then navigate: reloads and Back never show the pay button again.
198	    this.session.completePayment({
199	      quoteNumber: createQuoteNumber(countryCode, now),
200	      countryCode,
201	      planName: chosen.plan.name,
202	      amount: chosen.finalPrice,
203	      currency: country.currency,
204	      numberLocale: country.numberLocale,
205	      paidAt: now.toISOString(),
206	    });
207	    void this.router.navigate(['..', 'confirmation'], {
208	      relativeTo: this.route,
209	      replaceUrl: true,
210	    });
211	  }
212	}
