1	import { ComponentFixture, TestBed } from '@angular/core/testing';
2	import { Router, provideRouter } from '@angular/router';
3	import { Observable, Subject, of } from 'rxjs';
4	import { Country } from '../../core/country/country.model';
5	import { QuoteSessionStore } from '../../core/session/quote-session.store';
6	import { Plan } from '../plan-list/data/plan.model';
7	import { PlanService } from '../plan-list/data/plan.service';
8	import { FormFieldDescriptor, FormSections } from '../quote-form/data/form-field.model';
9	import { FormFieldService } from '../quote-form/data/form-field.service';
10	import { WizardCountry } from '../quote-wizard/wizard-country.service';
11	import { PaymentService } from './payment/payment.service';
12	import { SummaryPage } from './summary.page';
13	
14	const TERMS = [{ type: 'paragraph' as const, children: [{ type: 'text' as const, text: 'Texto de términos' }] }];
15	
16	const COUNTRY: Country = {
17	  code: 'co',
18	  name: 'Colombia',
19	  legalAge: 18,
20	  currency: 'COP',
21	  numberLocale: 'es-CO',
22	  driverAgeBands: [],
23	  vehicleAgeBands: [],
24	  termsAndConditions: TERMS,
25	  iconUrl: null,
26	  iconAlt: '',
27	};
28	
29	function field(key: string, label: string, section: 'policyholder' | 'vehicle', masked = false): FormFieldDescriptor {
30	  return {
31	    key,
32	    label,
33	    type: 'text',
34	    required: true,
35	    helpText: null,
36	    placeholder: null,
37	    errorMessage: '',
38	    order: 1,
39	    section,
40	    options: [],
41	    rules: { type: 'text', required: true, min: null, max: null, pattern: null, validators: [] },
42	    inputLimits: { allowedCharacters: null, maxLength: null },
43	    maskedInSummary: masked,
44	  };
45	}
46	
47	const FIELDS: FormSections = {
48	  policyholder: [field('fullName', 'Nombre', 'policyholder'), field('documentNumber', 'Cédula', 'policyholder', true)],
49	  vehicle: [field('plate', 'Placa', 'vehicle')],
50	};
51	
52	const PLAN: Plan = {
53	  id: 'p1',
54	  name: 'Plan Total',
55	  shortDescription: 'Todo cubierto',
56	  basePrice: 189000,
57	  coverages: [],
58	  benefits: [],
59	  highlighted: false,
60	};
61	
62	describe('US-03 · FR-001–FR-010 summary page', () => {
63	  let session: QuoteSessionStore;
64	  let navigate: ReturnType<typeof vi.spyOn>;
65	  let paySubject: Subject<'approved' | 'rejected'>;
66	  let pay: ReturnType<typeof vi.fn<(values: unknown, keys: string[]) => Observable<'approved' | 'rejected'>>>;
67	  let plans: Plan[];
68	  let fixture: ComponentFixture<SummaryPage>;
69	  let el: HTMLElement;
70	
71	  async function setup(country: Country = COUNTRY): Promise<void> {
72	    TestBed.inject(WizardCountry).set(country);
73	    fixture = TestBed.createComponent(SummaryPage);
74	    el = fixture.nativeElement;
75	    await fixture.whenStable();
76	  }
77	
78	  const button = (text: string) =>
79	    Array.from(el.querySelectorAll('button')).find((b) => b.textContent?.includes(text));
80	  const payButton = () => (button('Quiero mi seguro') ?? button('Procesando')) as HTMLButtonElement;
81	  const checkbox = () => el.querySelector<HTMLInputElement>('input[type="checkbox"]')!;
82	
83	  async function accept(): Promise<void> {
84	    checkbox().click();
85	    await fixture.whenStable();
86	  }
87	
88	  beforeEach(() => {
89	    sessionStorage.clear();
90	    paySubject = new Subject();
91	    pay = vi.fn().mockReturnValue(paySubject.asObservable());
92	    plans = [PLAN];
93	    TestBed.configureTestingModule({
94	      providers: [
95	        provideRouter([]),
96	        { provide: PlanService, useValue: { load: () => of(plans) } },
97	        { provide: FormFieldService, useValue: { load: () => of(FIELDS) } },
98	        { provide: PaymentService, useValue: { pay } },
99	      ],
100	    });
101	    session = TestBed.inject(QuoteSessionStore);
102	    session.start('co');
103	    session.saveStep1({ fullName: 'Ana Prueba', documentNumber: '1020304050', plate: 'ABC123' });
104	    session.markStep1Completed();
105	    session.savePlan('p1');
106	    navigate = vi.spyOn(TestBed.inject(Router), 'navigate').mockResolvedValue(true);
107	  });
108	
109	  it('FR-001 / FR-003 shows the data with the document masked and the plan price', async () => {
110	    await setup();
111	    expect(el.textContent).toContain('Ana Prueba');
112	    expect(el.textContent).toContain('••••••4050');
113	    expect(el.textContent).not.toContain('1020304050');
114	    expect(el.textContent).toContain('Plan Total');
115	  });
116	
117	  it('FR-004 keeps "Quiero mi seguro" disabled until the terms are accepted, and remembers the acceptance', async () => {
118	    await setup();
119	    expect(payButton().disabled).toBe(true);
120	    await accept();
121	    expect(payButton().disabled).toBe(false);
122	    expect(session.readTermsAccepted()).toBe(true);
123	  });
124	
125	  it('FR-007 a double press calls the payment once and disables the controls while processing', async () => {
126	    await setup();
127	    await accept();
128	    payButton().click();
129	    payButton().click();
130	    await fixture.whenStable();
131	    expect(pay).toHaveBeenCalledTimes(1);
132	    expect(pay).toHaveBeenCalledWith(expect.objectContaining({ documentNumber: '1020304050' }), ['documentNumber']);
133	    expect(payButton().disabled).toBe(true);
134	    expect(payButton().getAttribute('aria-busy')).toBe('true');
135	    expect(payButton().textContent).toContain('Procesando…');
136	    expect(checkbox().disabled).toBe(true);
137	  });
138	
139	  it('FR-008 a rejected payment shows an alert, keeps data and acceptance, and allows a retry', async () => {
140	    await setup();
141	    await accept();
142	    payButton().click();
143	    paySubject.next('rejected');
144	    await fixture.whenStable();
145	
146	    expect(el.querySelector('[role="alert"]')?.textContent).toContain('No pudimos procesar tu pago.');
147	    expect(session.readStep1()['documentNumber']).toBe('1020304050');
148	    expect(session.readTermsAccepted()).toBe(true);
149	    expect(checkbox().checked).toBe(true);
150	    expect(session.readReceipt()).toBeNull();
151	    expect(navigate).not.toHaveBeenCalled();
152	
153	    paySubject = new Subject();
154	    pay.mockReturnValue(paySubject.asObservable());
155	    expect(payButton().disabled).toBe(false);
156	    payButton().click();
157	    expect(pay).toHaveBeenCalledTimes(2);
158	  });
159	
160	  it('FR-009 an approved payment saves the receipt and goes to the confirmation', async () => {
161	    await setup();
162	    await accept();
163	    payButton().click();
164	    paySubject.next('approved');
165	    await fixture.whenStable();
166	
167	    const receipt = session.readReceipt();
168	    expect(receipt).toMatchObject({
169	      countryCode: 'co',
170	      planName: 'Plan Total',
171	      amount: 189000,
172	      currency: 'COP',
173	      numberLocale: 'es-CO',
174	    });
175	    expect(receipt?.quoteNumber).toMatch(/^CO-\d{8}-[A-Z2-9]{6}$/);
176	    expect(session.readStep1()).toEqual({});
177	    expect(navigate).toHaveBeenCalledWith(['..', 'confirmation'], expect.objectContaining({ replaceUrl: true }));
178	  });
179	
180	  it('FR-010 a plan that is no longer offered clears the choice and goes to the plan list', async () => {
181	    plans = [{ ...PLAN, id: 'other' }];
182	    await setup();
183	    expect(session.readPlanId()).toBeNull();
184	    expect(navigate).toHaveBeenCalledWith(['..', 'plans'], expect.anything());
185	  });
186	
187	  it('FR-005 a country without terms shows an error and keeps the CTA disabled', async () => {
188	    await setup({ ...COUNTRY, termsAndConditions: [] });
189	    expect(el.querySelector('[role="alert"]')?.textContent).toContain('términos y condiciones');
190	    expect(el.querySelector('input[type="checkbox"]')).toBeNull();
191	    expect(payButton().disabled).toBe(true);
192	  });
193	});
