1	import type { RichTextBlock, RichTextInline, RichTextListItem } from './rich-text.model';
2	
3	const ALLOWED_LINK_PROTOCOLS: readonly string[] = ['https:', 'http:', 'mailto:'];
4	
5	function isRecord(value: unknown): value is Record<string, unknown> {
6	  return typeof value === 'object' && value !== null && !Array.isArray(value);
7	}
8	
9	function isSafeUrl(url: unknown): url is string {
10	  if (typeof url !== 'string') return false;
11	  try {
12	    return ALLOWED_LINK_PROTOCOLS.includes(new URL(url.trim()).protocol);
13	  } catch {
14	    return false;
15	  }
16	}
17	
18	function mapInlines(raw: unknown): RichTextInline[] {
19	  if (!Array.isArray(raw)) return [];
20	  const result: RichTextInline[] = [];
21	  for (const node of raw) {
22	    if (!isRecord(node)) continue;
23	    if (node['type'] === 'text' && typeof node['text'] === 'string') {
24	      const text: RichTextInline = { type: 'text', text: node['text'] };
25	      if (node['bold'] === true) text.bold = true;
26	      if (node['italic'] === true) text.italic = true;
27	      if (node['underline'] === true) text.underline = true;
28	      result.push(text);
29	    } else if (node['type'] === 'link') {
30	      const children = mapInlines(node['children']);
31	      if (isSafeUrl(node['url'])) {
32	        result.push({ type: 'link', url: node['url'].trim(), children });
33	      } else {
34	        result.push(...children);
35	      }
36	    }
37	  }
38	  return result;
39	}
40	
41	function mapBlock(node: Record<string, unknown>): RichTextBlock | null {
42	  switch (node['type']) {
43	    case 'paragraph':
44	    case 'quote':
45	      return { type: node['type'], children: mapInlines(node['children']) };
46	    case 'heading': {
47	      const level = node['level'];
48	      const safe = typeof level === 'number' && level >= 1 && level <= 6 ? Math.trunc(level) : 2;
49	      return {
50	        type: 'heading',
51	        level: safe as 1 | 2 | 3 | 4 | 5 | 6,
52	        children: mapInlines(node['children']),
53	      };
54	    }
55	    case 'list': {
56	      const items: RichTextListItem[] = [];
57	      if (Array.isArray(node['children'])) {
58	        for (const item of node['children']) {
59	          if (isRecord(item) && item['type'] === 'list-item') {
60	            items.push({ type: 'list-item', children: mapInlines(item['children']) });
61	          }
62	        }
63	      }
64	      return {
65	        type: 'list',
66	        format: node['format'] === 'ordered' ? 'ordered' : 'unordered',
67	        children: items,
68	      };
69	    }
70	    default:
71	      return null;
72	  }
73	}
74	
75	/** Keeps the supported blocks, drops images, code and unknown types; missing input gives []. */
76	export function mapRichText(raw: unknown): RichTextBlock[] {
77	  if (!Array.isArray(raw)) return [];
78	  const blocks: RichTextBlock[] = [];
79	  for (const node of raw) {
80	    if (!isRecord(node)) continue;
81	    const block = mapBlock(node);
82	    if (block) blocks.push(block);
83	  }
84	  return blocks;
85	}
